V = "Harvest"
CS = "Vendor case study"
B = "https://www.getharvest.com/customers/"
LIVE = "Story still live on getharvest.com/customers (2026). Harvest (Bending Spoons) raised prices sharply in 2026 — strong switch-pitch timing. "
PA = "Harvest 2026 price hike victim candidate — pitch Tavilo flat plans as cheaper Harvest replacement with import help; "
def r(slug, first, **k):
    old = first[:4] < "2023" if first else False
    d = dict(vendor=V, evidence_type=CS, source_url=B + slug, source_publication_date=first,
             status="PROBABLE" if old else "CURRENT",
             status_reason=("Live but old vendor story (first archived %s); current use not re-confirmed" % first) if old else "Vendor story 2023+ / still live",
             confidence_score=60 if old else 85)
    d.update(k)
    if "pitch_angle" in k: d["pitch_angle"] = PA + k["pitch_angle"]
    d["notes"] = LIVE + k.get("notes", "")
    return d
